messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>3D Car Race</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { background: #000; overflow: hidden; font-family: 'Segoe UI', sans-serif; }
  canvas { display: block; }
  #ui {
    position: fixed; top: 20px; left: 50%; transform: translateX(-50%);
    text-align: center; pointer-events: none; z-index: 10;
  }
  #ui h1 { color: #fff; font-size: 28px; margin-bottom: 8px; text-shadow: 0 2px 6px rgba(0,0,0,0.7); }
  #ui .score { font-size: 20px; color: #ddd; margin-bottom: 12px; }
  #ui .status { font-size: 16px; color: #aaa; }
  #ui .winner { color: #ff4444; font-size: 24px; font-weight: bold; animation: pulse 1s ease-in-out infinite alternate; }
  @keyframes pulse { from { opacity: 1; } to { opacity: 0.6; } }
  #track-label {
    position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%);
    color: #666; font-size: 12px; text-align: center; letter-spacing: 2px; text-transform: uppercase;
  }
</style>
</head>
<body>
<div id="ui">
  <h1>🏁 CAR RACE</h1>
  <div class="score" id="score">Position: —</div>
  <div class="status" id="status">Blue leads — Red catching up!</div>
</div>
<div id="track-label">Track ahead &nbsp;|&nbsp; Finish line &nbsp;|&nbsp; Loop forever</div>
<script type="module">
  import * as THREE from './three.module.js';

  // ── Scene Setup ──
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x87CEEB);
  scene.fog = new THREE.FogExp2(0x87CEEB, 0.008);

  const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 2000);
  camera.position.set(0, 40, 80);
  camera.lookAt(0, 0, 200);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  document.body.appendChild(renderer.domElement);

  // ── Lighting ──
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
  scene.add(ambientLight);
  const dirLight = new THREE.DirectionalLight(0xffffff, 0.9);
  dirLight.position.set(100, 150, 100);
  scene.add(dirLight);

  // ── Ground (long track) ──
  const groundGeo = new THREE.PlaneGeometry(4000, 800, 200, 200);
  const groundMat = new THREE.MeshStandardMaterial({ color: 0x2d4a27, roughness: 0.9, metalness: 0.1 });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  // ── Skybox (simple gradient sphere) ──
  const skyGeo = new THREE.SphereGeometry(3000, 32, 32);
  const skyMat = new THREE.ShaderMaterial({
    uniforms: {
      uTopColor: { value: new THREE.Color(0x4488ff) },
      uBottomColor: { value: new THREE.Color(0x88bbff) },
      uMidColor: { value: new THREE.Color(0xcceeff) },
    },
    vertexShader: `
      uniform vec3 uTopColor, uBottomColor, uMidColor;
      varying vec2 vUv;
      void main() {
        vUv = uv;
        outPosition = position;
      }
    `,
    fragmentShader: `
      uniform vec3 uTopColor, uBottomColor, uMidColor;
      varying vec2 vUv;
      void main() {
        float t = 1.0 - vUv.y; // 1 at top, 0 at bottom
        vec3 top = uTopColor;
        vec3 bot = uBottomColor;
        vec3 mid = uMidColor;
        vec3 color;
        if (t > 0.5) color = mix(top, mid, (t - 0.5) * 2.0);
        else        color = mix(mid, bot, (1.0 - t) * 2.0);
        gl_FragColor = vec4(color, 1.0);
      }
    `,
    side: THREE.BackSide
  });
  const sky = new THREE.Mesh(skyGeo, skyMat);
  scene.add(sky);

  // ── Finish Line ──
  const finishGeo = new THREE.PlaneGeometry(60, 3, 2, 2);
  const finishMat = new THREE.MeshStandardMaterial({ color: 0xff4444, transparent: true, opacity: 0.8 });
  const finish = new THREE.Mesh(finishGeo, finishMat);
  finish.position.set(0, 0, 200);
  finish.rotation.x = -Math.PI / 2;
  scene.add(finish);

  // Finish line dashed effect
  const dashGeo = new THREE.PlaneGeometry(60, 3, 2, 20);
  const dashMat = new THREE.MeshBasicMaterial({ color: 0xff4444, transparent: true, opacity: 0.5 });
  const dash = new THREE.Mesh(dashGeo, dashMat);
  dash.position.set(0, 0, 200);
  dash.rotation.x = -Math.PI / 2;
  scene.add(dash);

  // ── Track Markings (white stripes along center) ──
  const stripeGeo = new THREE.PlaneGeometry(4000, 0.3, 100, 20);
  const stripeMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.4 });
  const stripe = new THREE.Mesh(stripeGeo, stripeMat);
  stripe.position.set(0, 0, 100);
  stripe.rotation.x = -Math.PI / 2;
  scene.add(stripe);

  // ── Lane markers ──
  for (let i = -300; i <= 300; i += 50) {
    const marker = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.5, 0.02), stripeMat);
    marker.position.set(0, 0.25, i);
    scene.add(marker);
  }

  // ── Car Models (procedural boxes with details) ──
  function createCar(color, name) {
    const group = new THREE.Group();

    // Body
    const body = new THREE.BoxGeometry(4, 1.5, 2.4);
    const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: 0.3, metalness: 0.7 });
    const bodyMesh = new THREE.Mesh(body, bodyMat);
    bodyMesh.position.y = 0.75;
    group.add(bodyMesh);

    // Roof
    const roof = new THREE.BoxGeometry(3.6, 0.6, 1.8);
    const roofMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(color).multiplyScalar(0.85), roughness: 0.2 });
    const roofMesh = new THREE.Mesh(roof, roofMat);
    roofMesh.position.set(0, 1.3, 0);
    group.add(roofMesh);

    // Windshield
    const windshield = new THREE.BoxGeometry(1.6, 0.8, 0.3);
    const windshieldMat = new THREE.MeshStandardMaterial({ color: 0x4488cc, transparent: true, opacity: 0.6 });
    const windshieldMesh = new THREE.Mesh(windshield, windshieldMat);
    windshieldMesh.position.set(0, 1.25, -0.7);
    group.add(windshieldMesh);

    // Wheels
    const wheelGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.35, 12, 8);
    const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
    const wheelPositions = [
      { x: -0.8, y: 0, z: -0.9 }, { x: 0.8, y: 0, z: -0.9 },
      { x: -0.8, y: 0, z: 0.9 },  { x: 0.8, y: 0, z: 0.9 },
    ];
    wheelPositions.forEach(w => {
      const wheel = new THREE.Mesh(wheelGeo, wheelMat);
      wheel.position.set(w.x, 0.2, w.z);
      wheel.rotation.y = Math.PI / 2;
      group.add(wheel);
    });

    // Headlights
    const headlightGeo = new THREE.BoxGeometry(0.5, 0.3, 0.15);
    const headlightMat = new THREE.MeshStandardMaterial({ color: 0xffaa00, emissive: 0xffaa00, emissiveIntensity: 0.5 });
    const hl1 = new THREE.Mesh(headlightGeo, headlightMat);
    hl1.position.set(-1.2, 1.0, -0.1);
    group.add(hl1);
    const hl2 = new THREE.Mesh(headlightGeo, headlightMat);
    hl2.position.set(1.2, 1.0, -0.1);
    group.add(hl2);

    // Taillights
    const taillightGeo = new THREE.BoxGeometry(0.5, 0.3, 0.15);
    const taillightMat = new THREE.MeshStandardMaterial({ color: 0xff2222, emissive: 0xff2222, emissiveIntensity: 0.6 });
    const tl1 = new THREE.Mesh(taillightGeo, taillightMat);
    tl1.position.set(-1.2, 1.0, 0.9);
    group.add(tl1);
    const tl2 = new THREE.Mesh(taillightGeo, taillightMat);
    tl2.position.set(1.2, 1.0, 0.9);
    group.add(tl2);

    // Name label
    const labelGeo = new THREE.PlaneGeometry(1.2, 0.4, 16, 16);
    const labelMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.9 });
    const label = new THREE.Mesh(labelGeo, labelMat);
    label.rotation.x = -Math.PI / 2;
    label.position.set(0, 1.6, 0.5);
    group.add(label);

    // Store name for UI
    group.userData.name = name;

    return group;
  }

  const blueCar = createCar(0x2266ff, 'BLUE');
  const redCar = createCar(0xff2244, 'RED');

  // ── Camera Follow ──
  function updateCamera() {
    const midZ = (blueCar.position.z + redCar.position.z) / 2;
    const targetZ = midZ + 60;
    camera.position.z = targetZ;
    camera.lookAt(0, 0, targetZ);
  }

  // ── Race Logic ──
  let raceActive = true;
  let racePhase = 'blue_leads'; // 'blue_leads' | 'red_catching' | 'red_overtakes' | 'red_wins'
  let winTimer = 0;
  let resetTimer = 0;

  // Blue car: starts ahead, steady speed
  const blueSpeed = 0.025;
  // Red car: starts behind, accelerates
  const redBaseSpeed = 0.015;
  const redAccel = 0.003;
  const redMaxSpeed = 0.045;

  // Starting positions
  blueCar.position.set(0, 0, 0);
  redCar.position.set(0, 0, -30); // Red starts 30 units behind

  // ── UI Elements ──
  const scoreEl = document.getElementById('score');
  const statusEl = document.getElementById('status');
  const winEl = document.getElementById('winner');

  function updateUI() {
    const bluePos = blueCar.position.z;
    const redPos = redCar.position.z;
    const diff = redPos - bluePos;

    if (racePhase === 'blue_leads') {
      scoreEl.textContent = `Position: Blue leads by ${Math.abs(diff).toFixed(1)} units`;
      statusEl.textContent = 'Blue leads — Red catching up!';
    } else if (racePhase === 'red_catching') {
      scoreEl.textContent = `Position: Red catching up — gap ${Math.abs(diff).toFixed(1)}`;
      statusEl.textContent = 'Red accelerating — catching up!';
    } else if (racePhase === 'red_overtakes') {
      scoreEl.textContent = `Position: Red is ahead by ${diff.toFixed(1)}!`;
      statusEl.textContent = 'RED OVERTAKES BLUE!';
    } else if (racePhase === 'red_wins') {
      scoreEl.textContent = `Position: Red crossed finish line!`;
      statusEl.textContent = 'RED WINS!';
      winEl.style.display = 'block';
      winEl.textContent = '🏆 RED WINS! 🏆';
    }

    updateCamera();
  }

  function resetRace() {
    blueCar.position.set(0, 0, 0);
    redCar.position.set(0, 0, -30);
    racePhase = 'blue_leads';
    winTimer = 0;
    winEl.style.display = 'none';
    statusEl.textContent = 'Blue leads — Red catching up!';
  }

  // ── Main Loop ──
  let frameCount = 0;
  let redSpeed = redBaseSpeed;
  let blueSpeed = blueSpeed;

  function animate() {
    requestAnimationFrame(animate);

    frameCount++;

    // ── Update car positions ──
    if (racePhase === 'blue_leads') {
      // Blue leads at steady speed
      blueCar.position.z += blueSpeed;
      redCar.position.z += redBaseSpeed;

      // Transition to red_catching when red is within 20 units
      if (redCar.position.z > blueCar.position.z + 20) {
        racePhase = 'red_catching';
      }
    } else if (racePhase === 'red_catching') {
      // Red accelerates
      redSpeed = Math.min(redSpeed + redAccel, redMaxSpeed);
      blueCar.position.z += blueSpeed;
      redCar.position.z += redSpeed;

      // Transition to red_overtakes when red passes blue
      if (redCar.position.z > blueCar.position.z) {
        racePhase = 'red_overtakes';
        statusEl.textContent = 'RED OVERTAKES BLUE!';
      }
    } else if (racePhase === 'red_overtakes') {
      // Red maintains speed, blue slows slightly
      redCar.position.z += redSpeed;
      blueCar.position.z += blueSpeed * 0.8;

      // Transition to red_wins when red crosses finish line
      if (blueCar.position.z > 200) {
        racePhase = 'red_wins';
        winTimer = 0;
      }
    } else if (racePhase === 'red_wins') {
      // Both cars slow to a stop at finish
      redCar.position.z += redSpeed * 0.5;
      blueCar.position.z += blueSpeed * 0.5;

      if (redCar.position.z > 200 && winTimer < 120) {
        winTimer++;
      }
      if (winTimer > 120) {
        resetRace();
      }
    }

    // ── Rotation for visual effect ──
    blueCar.rotation.y = Math.sin(frameCount * 0.02) * 0.05;
    redCar.rotation.y = Math.sin(frameCount * 0.02 + 1) * 0.05;

    // ── Update UI ──
    updateUI();

    // ── Render ──
    renderer.render(scene, camera);
  }

  // ── Resize Handler ──
  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });

  // ── Start ──
  animate();
</script>
</body>
</html>
```
